package net.officefloor.hq.app.person;

import java.util.stream.Stream;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Gives the person the alias; refuses one equal, as names are compared, to any name or alias on the sheet. */
public class AddAlias {
    public void add(@Val AliasInput input, @Val Person person, PersonRepository repository) throws BadRequestException {
        if (repository.nameTaken(person.getSheetId(), input.alias(), null)
                || !repository.addAlias(person, input.alias())) {
            throw new BadRequestException(PersonRepository.NAME_TAKEN);
        }
        person.setAliases(PersonName.sorted(Stream.concat(person.getAliases().stream(), Stream.of(input.alias())).toList()));
    }
}
package net.officefloor.hq.app.person;

import java.util.stream.Stream;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names another person on the sheet as the person's patron; refuses the person themselves and a patron they have already. */
public class AddPatron {
    public void add(@Val PatronInput input, @Val Person person, PersonRepository repository, Out<PatronAdded> added)
            throws BadRequestException {
        Person patron = repository.find(person.getSheetId(), input.patronId());
        if (patron == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        if (patron.getId() == person.getId()) {
            throw new BadRequestException("A person cannot be their own patron");
        }
        if (!repository.addPatron(person.getId(), patron.getId())) {
            throw new BadRequestException(patron.getName() + " is already a patron; reload the sheet");
        }
        person.setPatrons(Stream.concat(person.getPatrons().stream(), Stream.of(patron.getName())).sorted().toList());
        added.set(new PatronAdded(patron));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The alias to give: trimmed, required, at most 200 characters, as a name is. Publishes it, with the user making the change. */
public class ValidateAlias {
    public void validate(@RequestBody AliasRequest request, Out<AliasInput> alias, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String typed = request == null || request.alias() == null ? "" : request.alias().trim();
        if (typed.isEmpty()) {
            throw new BadRequestException("Enter an alias");
        }
        if (typed.length() > 200) {
            throw new BadRequestException("An alias is at most 200 characters");
        }
        alias.set(new AliasInput(typed));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Which person to name as patron. Publishes it, with the user making the change. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronInput> patron, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.patron() == null) {
            throw new BadRequestException("Choose a patron");
        }
        patron.set(new PatronInput(request.patron()));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date (blank: the sheet's today); refuses a person already retired. */
public class RetirePerson {
    public void retire(@Val RetireInput input, @Val Person person, PersonRepository repository, SheetRepository sheets)
            throws BadRequestException {
        if (person.isRetired()) {
            throw new BadRequestException("That person is already retired");
        }
        LocalDate from = input.date() != null ? input.date() : sheets.today(person.getSheetId());
        if (!repository.retire(person.getId(), from)) {
            throw new BadRequestException("That person was retired by someone else; reload the sheet");
        }
        person.setRetiredFrom(from);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

